function drawMediaAsset(ctx,item,index,x,y,w,h,r=30,showLabel=true){ctx.fillStyle='#e7ebef';rounded(ctx,x,y,w,h,r);ctx.fill();ctx.save();rounded(ctx,x,y,w,h,r);ctx.clip();const source=item?.img||item?.videoEl;if(source){const sw=source.videoWidth||source.width,sh=source.videoHeight||source.height,setting=mediaSetting(index),base=Math.max(w/sw,h/sh),scale=base*(setting.scale||1),dw=sw*scale,dh=sh*scale;ctx.fillStyle='#f3f6f9';ctx.fillRect(x,y,w,h);ctx.drawImage(source,x+(w-dw)/2+(setting.x||0),y+(h-dh)/2+(setting.y||0),dw,dh)}else{ctx.fillStyle='#cad3dc';ctx.fillRect(x,y,w,h)}if(showLabel){ctx.fillStyle='rgba(6,41,90,.72)';ctx.font='900 22px Arial';ctx.fillText(String(index+1).padStart(2,'0'),x+18,y+34)}ctx.restore()}
function drawMedia(ctx,motion={reveal:1,time:0}){drawCoverStage(ctx,motion,false);const reveal=motion.reveal??1;motionGroup(ctx,phase(reveal,.05,.75),65,()=>{if(!mediaItems.length){ctx.fillStyle='rgba(255,255,255,.08)';rounded(ctx,108,500,864,720,44);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.38)';ctx.lineWidth=3;ctx.setLineDash([14,12]);rounded(ctx,140,532,800,656,34);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='rgba(255,255,255,.76)';ctx.textAlign='center';ctx.font='700 32px Arial';ctx.fillText('OPTIONAL PHOTO / VIDEO',W/2,840);ctx.textAlign='left'}else{const items=mediaItems.slice(0,10),rects=mediaLayouts(items.length);items.forEach((item,i)=>{const rect={...rects[i],y:rects[i].y+10,h:Math.max(120,rects[i].h+16)};drawMediaAsset(ctx,item,i,rect.x,rect.y,rect.w,rect.h,rect.r,false)})}});drawResultsBand(ctx,'','media',motion)}
function drawNext(ctx,motion={reveal:1,time:0}){drawCoverStage(ctx,motion);const reveal=motion.reveal??1,ev=state.events.filter(e=>e.name||e.date||e.location).slice(0,4);motionGroup(ctx,phase(reveal,0,.35),46,()=>{ctx.textAlign='center';ctx.fillStyle='rgba(255,255,255,.94)';ctx.font='italic 900 82px Georgia,serif';ctx.fillText('Follow the Seahorses',W/2,365);ctx.fillStyle=WHITE;ctx.font='900 62px Arial';ctx.fillText('NEXT ON THE SCHEDULE',W/2,464);ctx.textAlign='left'});const startY=748,endY=1510,gap=28,count=Math.max(1,ev.length),cardH=Math.min(188,Math.max(150,(endY-startY-gap*(count-1))/count));if(!ev.length){motionGroup(ctx,phase(reveal,.18,.72),46,()=>{ctx.fillStyle='rgba(255,255,255,.07)';rounded(ctx,70,845,940,190,28);ctx.fill();ctx.fillStyle=WHITE;ctx.font='900 42px Arial';ctx.fillText('SCHEDULE COMING SOON',102,923);ctx.fillStyle='rgba(215,228,239,.82)';ctx.font='800 27px Arial';ctx.fillText('Add upcoming events in the schedule fields.',102,971)})}ev.forEach((e,i)=>motionGroup(ctx,phase(reveal,.16+i*.10,.58+i*.10),46,()=>{const y=startY+i*(cardH+gap);ctx.fillStyle='rgba(255,255,255,.07)';rounded(ctx,70,y,940,cardH,28);ctx.fill();ctx.fillStyle=ORANGE;ctx.font='900 32px Arial';ctx.fillText(e.date||'',102,y+50);ctx.fillStyle=WHITE;const title=(e.name||'').toUpperCase();ctx.font=`900 ${fit(ctx,title,860,46,30)}px Arial`;ctx.fillText(title,102,y+104);ctx.fillStyle='rgba(215,228,239,.82)';ctx.font='800 25px Arial';ctx.fillText(e.location||'',102,y+140)}));drawResultsBand(ctx,'','next',motion)}
