function sync(){state.eventName=q('rrsEvent')?.value||'Regatta Results';state.date=q('rrsDate')?.value||'';state.location=q('rrsLocation')?.value||'';state.place=q('rrsPlace')?.value||'';state.team=q('rrsTeam')?.value||'';state.a=q('rrsA')?.value||'';state.b=q('rrsB')?.value||'';state.total=q('rrsTotal')?.value||'';state.coverScale=(parseFloat(q('rrsCoverScale')?.value)||100)/100;state.coverX=parseFloat(q('rrsCoverX')?.value)||0;state.coverY=parseFloat(q('rrsCoverY')?.value)||0;state.coverOpacity=(parseFloat(q('rrsCoverOpacity')?.value)||100)/100;state.events=[0,1,2,3].map(i=>({name:q('rrsNextName'+i)?.value||'',date:q('rrsNextDate'+i)?.value||'',location:q('rrsNextLocation'+i)?.value||''}));state.mediaSettings=Array.from({length:10},(_,i)=>({scale:(parseFloat(q('rrsMediaScale'+i)?.value)||100)/100,x:parseFloat(q('rrsMediaX'+i)?.value)||0,y:parseFloat(q('rrsMediaY'+i)?.value)||0}));draw()}
const PROJECT_KEY='csms-regatta-results-story-v1',DRAFTS_KEY='csms-regatta-results-drafts-v1',ACTIVE_DRAFT_KEY='csms-regatta-results-active-draft-v1';
function setProjectStatus(text){if(q('rrsProjectStatus'))q('rrsProjectStatus').textContent=text}
function readDrafts(){try{const value=JSON.parse(localStorage.getItem(DRAFTS_KEY)||'[]');return Array.isArray(value)?value:[]}catch{return []}}
