function loadImageFile(file,cb){if(!file)return;const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{cb(img);URL.revokeObjectURL(url);draw()};img.src=url}
const ASSET_DB='csms-regatta-results-assets',ASSET_STORE='assets';
function openAssetDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(ASSET_DB,1);request.onupgradeneeded=()=>request.result.createObjectStore(ASSET_STORE);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function storeAsset(key,value){const db=await openAssetDb();return new Promise((resolve,reject)=>{const tx=db.transaction(ASSET_STORE,'readwrite');tx.objectStore(ASSET_STORE).put(value,key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function storedAsset(key){const db=await openAssetDb();return new Promise((resolve,reject)=>{const tx=db.transaction(ASSET_STORE,'readonly'),request=tx.objectStore(ASSET_STORE).get(key);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);tx.oncomplete=()=>db.close()})}
async function deleteStoredAsset(key){const db=await openAssetDb();return new Promise((resolve,reject)=>{const tx=db.transaction(ASSET_STORE,'readwrite');tx.objectStore(ASSET_STORE).delete(key);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
function assetKey(kind){return currentDraftId?`draft:${currentDraftId}:${kind}`:kind}
function imageFromBlob(blob){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(blob),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Image could not be restored'))};img.src=url})}
function videoFromBlob(blob){return new Promise(resolve=>{const url=URL.createObjectURL(blob),video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='metadata';video.src=url;video.onloadeddata=()=>{try{video.currentTime=Math.min(.1,video.duration||.1)}catch{}resolve({name:blob.name||'Regatta video',video:true,videoEl:video,videoUrl:url})};video.onerror=()=>resolve({name:blob.name||'Regatta video',video:true})})}
async function mediaItemFromFile(file){return file.type?.startsWith('image/')?{name:file.name,img:await imageFromBlob(file)}:await videoFromBlob(file)}
function renderMediaControls(){const host=q('rrsMediaControls');if(!host)return;host.innerHTML=mediaItems.length?mediaItems.slice(0,10).map((item,i)=>{const setting=mediaSetting(i),name=String(item.name||`Media ${i+1}`).replace(/[<>&"]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]));return `<div class="rrsMediaControl"><strong>${i+1}. ${name}</strong><label>Scale<input id="rrsMediaScale${i}" type="range" min="80" max="190" value="${Math.round((setting.scale||1)*100)}"></label><label>Left / right<input id="rrsMediaX${i}" type="range" min="-320" max="320" value="${setting.x||0}"></label><label>Up / down<input id="rrsMediaY${i}" type="range" min="-320" max="320" value="${setting.y||0}"></label></div>`}).join(''):'';host.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{sync();saveProject()}))}
async function restoreStoredAssets(){if(assetRestorePromise)return assetRestorePromise;if(!currentDraftId){draw();return}assetRestorePromise=(async()=>{try{const draft=readDrafts().find(item=>item.id===currentDraftId);let [savedScore,savedMedia]=await Promise.all([storedAsset(assetKey('score')),storedAsset(assetKey('media'))]);if(draft?.legacyAssets){if(!savedScore)savedScore=await storedAsset('score');if(!savedMedia)savedMedia=await storedAsset('media')}if(savedScore&&!scoreImage)scoreImage=await imageFromBlob(savedScore);if(!mediaItems.length&&Array.isArray(savedMedia)&&savedMedia.length){mediaItems=await Promise.all(savedMedia.map(mediaItemFromFile));renderMediaControls()}draw()}catch(err){console.warn('[CSMS] Stored regatta assets could not be restored',err)}})();try{await assetRestorePromise}finally{assetRestorePromise=null}}
function setScoreReaderStatus(text){scoreReaderStatus=text;if(q('rrsReaderStatus'))q('rrsReaderStatus').textContent=text}
