async function prepareScoreImage(file){const bitmap=await createImageBitmap(file),scale=Math.max(1,Math.min(2,1800/bitmap.width)),canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle=WHITE;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.filter='grayscale(1) contrast(1.35)';ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas}
function parseScoreRows(text){return (text||'').split(/\n+/).map(line=>line.replace(/\s+/g,' ').trim()).filter(Boolean).map(line=>{const nums=(line.match(/\b\d{1,4}\b/g)||[]).map(Number),rankMatch=line.match(/^\D*(\d{1,2})\b/),rank=rankMatch?Number(rankMatch[1]):null,values=rank&&nums[0]===rank?nums.slice(1):nums;if(nums.length<3||!/[A-Za-z]/.test(line))return null;let scores=null;for(let i=values.length-3;i>=0;i--){const a=values[i],b=values[i+1],total=values[i+2];if(total>=a&&total>=b&&Math.abs(a+b-total)<=2){scores=[a,b,total];break}}if(!scores&&rank){const useFirstPair=values.length>=3&&(values.at(-1)>=Math.max(values.at(-2),values.at(-3))||values.at(-3)>20),a=useFirstPair?values.at(-3):values.at(-2),b=useFirstPair?values.at(-2):values.at(-1);if(Number.isFinite(a)&&Number.isFinite(b))scores=[a,b,a+b]}if(!scores)return null;const team=line.replace(/\b\d{1,4}\b/g,' ').replace(/\s+/g,' ').trim();return {line,team,rank,a:scores[0],b:scores[1],total:scores[2]}}).filter(Boolean)}
function ocrWords(data){if(data?.words?.length)return data.words;if(data?.blocks?.length)return data.blocks.flatMap(block=>(block.paragraphs||[]).flatMap(paragraph=>(paragraph.lines||[]).flatMap(line=>line.words||[])));if(data?.tsv){return data.tsv.split('\n').slice(1).map(line=>line.split('\t')).filter(parts=>parts.length>=12&&parts[11]?.trim()).map(parts=>{const left=Number(parts[6]),top=Number(parts[7]),width=Number(parts[8]),height=Number(parts[9]);return {text:parts.slice(11).join('\t'),bbox:{x0:left,y0:top,x1:left+width,y1:top+height}}})}return []}
function spatialScoreText(data){const usable=ocrWords(data).filter(word=>word?.text?.trim()&&word?.bbox).map(word=>({text:word.text.trim(),x:word.bbox.x0,y:(word.bbox.y0+word.bbox.y1)/2,h:Math.max(1,word.bbox.y1-word.bbox.y0)})).sort((a,b)=>a.y-b.y||a.x-b.x),rows=[];usable.forEach(word=>{let row=rows.find(candidate=>Math.abs(candidate.y-word.y)<=Math.max(16,Math.min(candidate.h,word.h)*.75));if(!row){row={y:word.y,h:word.h,words:[]};rows.push(row)}row.words.push(word);row.y=(row.y*(row.words.length-1)+word.y)/row.words.length;row.h=Math.max(row.h,word.h)});return rows.sort((a,b)=>a.y-b.y).map(row=>row.words.sort((a,b)=>a.x-b.x).map(word=>word.text).join(' ')).join('\n')}
function parseSpatialScoreRows(data){const words=ocrWords(data).filter(word=>word?.text?.trim()&&word?.bbox).map(word=>({text:word.text.trim(),cx:(word.bbox.x0+word.bbox.x1)/2,y:(word.bbox.y0+word.bbox.y1)/2,h:Math.max(1,word.bbox.y1-word.bbox.y0)}));if(!words.length)return [];const maxX=Math.max(...words.map(word=>word.cx)),topY=Math.min(...words.map(word=>word.y)),headerWord=value=>words.filter(word=>word.text.replace(/[^A-Z]/gi,'').toUpperCase()===value).sort((a,b)=>a.y-b.y)[0],aHead=headerWord('A')||{cx:maxX*.75,y:topY},bHead=headerWord('B')||{cx:maxX*.87,y:topY},totHead=headerWord('TOT')||{cx:maxX*.97,y:topY},rows=[];words.filter(word=>word.y>Math.min(aHead.y,bHead.y,totHead.y)+20).sort((a,b)=>a.y-b.y||a.cx-b.cx).forEach(word=>{let row=rows.find(candidate=>Math.abs(candidate.y-word.y)<=Math.max(16,Math.min(candidate.h,word.h)*.75));if(!row){row={y:word.y,h:word.h,words:[]};rows.push(row)}row.words.push(word);row.y=(row.y*(row.words.length-1)+word.y)/row.words.length;row.h=Math.max(row.h,word.h)});const gap=Math.min(Math.abs(bHead.cx-aHead.cx),Math.abs(totHead.cx-bHead.cx)),numberNear=(row,x)=>{const candidates=row.words.map(word=>({word,value:Number(word.text.replace(/[^0-9]/g,''))})).filter(item=>/^\D*\d{1,3}\D*$/.test(item.word.text)&&Number.isFinite(item.value)&&Math.abs(item.word.cx-x)<gap*.65).sort((a,b)=>Math.abs(a.word.cx-x)-Math.abs(b.word.cx-x));return candidates[0]?.value};return rows.map(row=>{const ordered=row.words.sort((a,b)=>a.cx-b.cx),rank=ordered.map(word=>({word,value:Number(word.text.replace(/[^0-9]/g,''))})).filter(item=>/^\d{1,2}$/.test(item.word.text)&&item.word.cx<aHead.cx*.55).sort((a,b)=>a.word.cx-b.word.cx)[0]?.value,a=numberNear(row,aHead.cx),b=numberNear(row,bHead.cx),line=ordered.map(word=>word.text).join(' ');return Number.isFinite(rank)&&Number.isFinite(a)&&Number.isFinite(b)?{line,team:line,rank,a,b,total:a+b}:null}).filter(Boolean)}
function scoreRanks(rows,key){const ordered=[...rows].sort((a,b)=>Number(a[key])-Number(b[key])||Number(a.total)-Number(b.total)||Number(a.rank)-Number(b.rank));return new Map(ordered.map((row,index)=>[row,index+1]))}
function rankList(rows,ranks){return rows.map(row=>ranks.get(row)).sort((a,b)=>a-b).map(rank=>`${rank}${ordinal(rank)}`).join(', ')}
function resultsFromRows(rows){const byRank=new Map;rows.filter(row=>row.rank).forEach(row=>{const current=byRank.get(row.rank),preferred=/CHRIST.{0,3}CHURCH|SEAHOR/i.test(row.line)||!current||row.line.length>current.line.length;if(preferred)byRank.set(row.rank,row)});if(byRank.size>=3)rows=[...byRank.values()];const christchurch=rows.filter(row=>/CHRIST.{0,3}CHURCH|SEAHOR/i.test(row.line));if(!rows.length||!christchurch.length)return null;const overallRanks=scoreRanks(rows,'total'),aRanks=scoreRanks(rows,'a'),bRanks=scoreRanks(rows,'b'),officialOverall=christchurch.every(row=>row.rank),overallList=officialOverall?christchurch.map(row=>row.rank).sort((a,b)=>a-b).map(rank=>`${rank}${ordinal(rank)}`).join(', '):rankList(christchurch,overallRanks);return {place:overallList,a:rankList(christchurch,aRanks),b:rankList(christchurch,bRanks),total:overallList,team:'Christchurch School',count:christchurch.length}}
function parseChristchurchResults(text){return resultsFromRows(parseScoreRows(text))}
function applyChristchurchResults(result){if(!result)return false;[['place','rrsPlace'],['team','rrsTeam'],['a','rrsA'],['b','rrsB'],['total','rrsTotal']].forEach(([k,id])=>{if(result[k]&&q(id))q(id).value=result[k]});sync();saveProject();setScoreReaderStatus(`Read ${result.count||1} Christchurch result${result.count===1?'':'s'}: overall ${state.total||state.place||'not found'}, A division ${state.a||'not found'}, B division ${state.b||'not found'}.`);return true}
async function readScoreSheet(file){if(!file||!file.type.startsWith('image/')){setScoreReaderStatus('Reader supports uploaded image score sheets.');return}const readerDraftId=currentDraftId;setScoreReaderStatus('Preparing score sheet...');let worker;try{const T=await loadScoreReader(),prepared=await prepareScoreImage(file);worker=await T.createWorker('eng',1,{logger:m=>{if(currentDraftId===readerDraftId&&m.status==='recognizing text')setScoreReaderStatus(`Reading score sheet... ${Math.round((m.progress||0)*100)}%`)}});await worker.setParameters({tessedit_pageseg_mode:'6',preserve_interword_spaces:'1',user_defined_dpi:'200'});const out=await worker.recognize(prepared,{}, {text:true,blocks:true,tsv:true}),plain=out?.data?.text||'',spatial=spatialScoreText(out?.data),spatialRows=parseSpatialScoreRows(out?.data),textRows=parseScoreRows(spatial),result=resultsFromRows(spatialRows)||resultsFromRows(textRows)||parseChristchurchResults(plain);if(currentDraftId!==readerDraftId)return;if(!applyChristchurchResults(result))setScoreReaderStatus('Could not find a Christchurch results row. You can still enter the results manually.')}catch(err){if(currentDraftId===readerDraftId)setScoreReaderStatus('Could not read the score sheet image. You can still enter the results manually.')}finally{await worker?.terminate?.()}}
function onScore(e){const file=e.target.files?.[0];if(!file)return;saveProject();storeAsset(assetKey('score'),file).catch(()=>{});loadImageFile(file,img=>scoreImage=img);readScoreSheet(file)}
function onCover(e){loadImageFile(e.target.files?.[0],img=>coverPhoto=img)}
