function addTemplateTile(){const list=q('templateLibraryList');if(!list||q('rrsTemplateTile'))return;const row=document.createElement('div');row.id='rrsTemplateTile';row.className='athleteItem csmsRecoveredRow';row.innerHTML=`<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%"><div><strong>${TEMPLATE_NAME}</strong><div style="font-size:12px;color:#60758c;margin-top:3px">Story video • score sheet → results → optional media → upcoming events</div></div><button type="button" style="border:0;border-radius:8px;padding:9px 12px;font-weight:800;background:#f4511e;color:white">Open</button></div>`;row.querySelector('button').addEventListener('click',open);list.prepend(row)}
